from qibo import matrices, gates
from qibo.symbols import Symbol

class H(Symbol):
    def __init__(self, q):
        super().__init__(q, matrices.H, "H")

    @property
    def calculate_gate(self):
        return gates.H(self.target_qubit)

h_symbol = H(0)
print(h_symbol._matrix)
```

