import unittest
from qibo import gates

def bool_commute(gate1, gate2):
    return gate1.commutes(gate2)

class TestCommute(unittest.TestCase):
    def test_hadamard_commute(self):
        gate1 = gates.H(0)
        gate2 = gates.H(0)
        self.assertTrue(bool_commute(gate1, gate2))
        print("H(0) and H(0) commute? True")

if __name__ == '__main__':
    unittest.main()
```

